export interface ApiSuccess<T = unknown> {
  success: 1;
  msg: string;
  info: T | null;
}

export interface ApiFailure {
  success: 0;
  code?: string;
  msg: string;
  info: null;
}

export type ApiEnvelope<T = unknown> = ApiSuccess<T> | ApiFailure;

export interface EsportUser {
  id: string;
  userName: string;
  isAdmin?: boolean;
  role?: string;
  teamId?: string | null;
  setting?: Record<string, unknown>;
}

