function clientIpFromRequest(req?: IncomingMessage): string {
  if (!req)
    return "";
  const raw
    = (req.headers["x-forwarded-for"] as string | undefined)?.split(",")[0]?.trim()
      || req.socket?.remoteAddress
      || "";
  return normalizeClientIp(raw);
}

